public static class ControlsAuditRunner {
 public static void Baseline(){SessionState.SetString("ControlsAuditLabel","before4");Run();}
 public static void Limits(){SessionState.SetString("ControlsAuditLabel","limits-fixed");Run();}
 public static void Edges(){SessionState.SetString("ControlsAuditLabel","edges");Run();}
 public static void Final(){SessionState.SetString("ControlsAuditLabel","after");Run();}
 static void Run(){SessionState.SetBool("ControlsAudit",true);SessionState.SetString("ControlsAuditDir",Path.Combine(Path.GetTempPath(),"DespachoControls-"+Guid.NewGuid().ToString("N")));EditorApplication.EnterPlaymode();}
 public static void Restart(){DeskPreferences.TestDirectory=DeskSaveStore.TestDirectory=File.ReadAllText("Logs/ControlsAudit-directory.txt");DeskPreferences.Load();AccessPreferences.Load();bool ok=JsonUtility.ToJson(AccessPreferences.Current)==File.ReadAllText("Logs/ControlsAudit-access-expected.txt")&&JsonUtility.ToJson(DeskPreferences.Current)==File.ReadAllText("Logs/ControlsAudit-desk-expected.txt");File.WriteAllText("Logs/ControlsAudit-restart.txt",ok?"PASS separate Unity process restores full accessibility and desk preferences":"FAIL restart");EditorApplication.Exit(ok?0:1);}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Before(){if(SessionState.GetBool("ControlsAudit",false))DeskPreferences.TestDirectory=DeskSaveStore.TestDirectory=SessionState.GetString("ControlsAuditDir","");}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void After(){if(!SessionState.GetBool("ControlsAudit",false))return;SessionState.SetBool("ControlsAudit",false);new GameObject("ControlsAuditProbe").AddComponent<ControlsAuditProbe>();}
